// ==================== BULLETPROOF PRINTING (NEVER BLOCKED BY POPUP BLOCKERS) ====================
function printViaIframeOrWindow(title, htmlContent) {
  // 1. Try hidden iframe first (100% bypasses popup blocker on all computers)
  try {
    let frame = document.getElementById('printExecutionIframe');
    if (!frame) {
      frame = document.createElement('iframe');
      frame.id = 'printExecutionIframe';
      frame.style.cssText = 'position:fixed;right:100%;bottom:100%;width:0;height:0;border:0;opacity:0;pointer-events:none;';
      document.body.appendChild(frame);
    }

    const doc = frame.contentWindow.document;
    doc.open();
    doc.write(htmlContent);
    doc.close();

    // Give browser time to parse SVG, styles, and images
    setTimeout(() => {
      try {
        frame.contentWindow.focus();
        frame.contentWindow.print();
      } catch (err) {
        console.warn('Iframe print error, falling back to window.open:', err);
        fallbackPrintWindow(title, htmlContent);
      }
    }, 450);
    return;
  } catch (e) {
    console.warn('Iframe setup failed, falling back:', e);
  }

  // 2. Fallback window.open
  fallbackPrintWindow(title, htmlContent);
}

function fallbackPrintWindow(title, htmlContent) {
  try {
    const w = window.open('', '_blank');
    if (w) {
      w.document.open();
      w.document.write(htmlContent);
      w.document.close();
      w.focus();
      setTimeout(() => {
        try { w.print(); } catch (e) {}
      }, 500);
    } else {
      showToast('Print window popup a in-block. Khawngaihin popup allow rawh.', 'warning');
    }
  } catch (err) {
    console.error('Fallback print window error:', err);
  }
}

// ==================== AUTO-FIXED EXCEL EXPORT (.XLSX) ====================
// Headings: MIZORAM PRESBYTERIAN KOHHRAN / (Presbyterian Church of India) / Kristian Thalai Pawl / Armed Veng South Branch
// Font: Mizo Synod Book Times (Times New Roman), Bold, Centered Headings & Card No (ktp001/2026)

function ensureXlsxLoaded(callback) {
  if (typeof XLSX !== 'undefined') {
    callback();
    return;
  }
  showToast('Excel library download mek a ni, nghak lawk...', 'info');
  const script = document.createElement('script');
  script.src = 'https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.bundle.js';
  script.onload = () => {
    callback();
  };
  script.onerror = () => {
    showToast('Online Excel library lak theih loh, CSV/Excel fallback hmangin a export dawn.', 'warning');
    exportToExcelFallback();
  };
  document.head.appendChild(script);
}

function exportToExcel() {
  if (!members || members.length === 0) {
    showToast('Export tur member record an awm lo.', 'error');
    return;
  }

  ensureXlsxLoaded(() => {
    runActualExcelExport();
  });
}

function runActualExcelExport() {
  // 1. If XLSX (with xlsx-js-style) is loaded, generate styled .xlsx
  if (typeof XLSX !== 'undefined') {
    const wsData = [
      ['MIZORAM PRESBYTERIAN KOHHRAN'],
      ['(Presbyterian Church of India)'],
      ['Kristian Thalai Pawl'],
      ['Armed Veng South Branch'],
      [], // blank line
      [
        'Serial No.',
        'Card No.',
        'Member Name (Hming)',
        'Nu / Pa Hming',
        'House No.',
        'Upa Bial',
        'Phone Number',
        'Group',
        'Thalai Kantu',
        'Kristian Thalai'
      ]
    ];

    // Append members with ktp001/2026 Card No and Group at last
    members.forEach((m, index) => {
      const cardNo = getMemberCardNo(m, index);
      const cleanPhone = (m.phone || '').replace(/\D/g, '');
      const formattedPhone = cleanPhone.length === 10
        ? `${cleanPhone.slice(0, 5)} ${cleanPhone.slice(5)}`
        : cleanPhone;

      wsData.push([
        index + 1,
        cardNo,
        m.name || '',
        m.parentsName || '',
        m.houseNo || '',
        m.upaBial || '',
        formattedPhone,
        m.group || 'Unassigned',
        m.thalaiKantu || 'Aw',
        m.kristianThalai || 'Aw'
      ]);
    });

    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // Merge Headings across all 10 columns (A to J)
    ws['!merges'] = [
      { s: { r: 0, c: 0 }, e: { r: 0, c: 9 } }, // Row 1: MIZORAM PRESBYTERIAN KOHHRAN
      { s: { r: 1, c: 0 }, e: { r: 1, c: 9 } }, // Row 2: (Presbyterian Church of India)
      { s: { r: 2, c: 0 }, e: { r: 2, c: 9 } }, // Row 3: Kristian Thalai Pawl
      { s: { r: 3, c: 0 }, e: { r: 3, c: 9 } }  // Row 4: Armed Veng South Branch
    ];

    // Row heights (Points)
    ws['!rows'] = [
      { hpt: 32 }, // Row 1
      { hpt: 24 }, // Row 2
      { hpt: 30 }, // Row 3
      { hpt: 26 }, // Row 4
      { hpt: 12 }, // Row 5 (Blank)
      { hpt: 26 }  // Row 6 (Table Headers)
    ];

    // Column widths
    ws['!cols'] = [
      { wch: 12 }, // Serial No.
      { wch: 16 }, // Card No. (ktp001/2026)
      { wch: 28 }, // Member Name (Hming)
      { wch: 26 }, // Nu / Pa Hming
      { wch: 16 }, // House No.
      { wch: 16 }, // Upa Bial
      { wch: 18 }, // Phone Number
      { wch: 16 }, // Group (At Last)
      { wch: 14 }, // Thalai Kantu
      { wch: 14 }  // Kristian Thalai
    ];

    const borderThin = {
      top: { style: 'thin', color: { rgb: 'CBD5E1' } },
      bottom: { style: 'thin', color: { rgb: 'CBD5E1' } },
      left: { style: 'thin', color: { rgb: 'CBD5E1' } },
      right: { style: 'thin', color: { rgb: 'CBD5E1' } }
    };

    // Row 1: MIZORAM PRESBYTERIAN KOHHRAN (CENTERED, 16pt, BOLD, TIMES NEW ROMAN)
    if (ws['A1']) {
      ws['A1'].s = {
        font: { name: 'Times New Roman', sz: 16, bold: true, color: { rgb: '000000' } },
        alignment: { horizontal: 'center', vertical: 'center' }
      };
    }

    // Row 2: (Presbyterian Church of India) (CENTERED, 12pt, ITALIC, TIMES NEW ROMAN)
    if (ws['A2']) {
      ws['A2'].s = {
        font: { name: 'Times New Roman', sz: 12, italic: true, bold: false, color: { rgb: '333333' } },
        alignment: { horizontal: 'center', vertical: 'center' }
      };
    }

    // Row 3: Kristian Thalai Pawl (CENTERED, 16pt, BOLD, TIMES NEW ROMAN)
    if (ws['A3']) {
      ws['A3'].s = {
        font: { name: 'Times New Roman', sz: 16, bold: true, color: { rgb: '000000' } },
        alignment: { horizontal: 'center', vertical: 'center' }
      };
    }

    // Row 4: Armed Veng South Branch (CENTERED, 13pt, BOLD, TIMES NEW ROMAN)
    if (ws['A4']) {
      ws['A4'].s = {
        font: { name: 'Times New Roman', sz: 13, bold: true, color: { rgb: '000000' } },
        alignment: { horizontal: 'center', vertical: 'center' }
      };
    }

    // Row 6: Column Headers (CENTERED, 12pt, BOLD, TIMES NEW ROMAN, LIGHT FILL)
    for (let c = 0; c < 10; c++) {
      const cellRef = XLSX.utils.encode_cell({ r: 5, c: c });
      if (ws[cellRef]) {
        ws[cellRef].s = {
          font: { name: 'Times New Roman', sz: 12, bold: true, color: { rgb: '0F172A' } },
          alignment: { horizontal: 'center', vertical: 'center' },
          fill: { fgColor: { rgb: 'F1F5F9' } },
          border: borderThin
        };
      }
    }

    // Data Rows (Rows >= 6)
    const range = XLSX.utils.decode_range(ws['!ref'] || 'A1:J6');
    for (let R = 6; R <= range.e.r; ++R) {
      if (!ws['!rows'][R]) ws['!rows'][R] = { hpt: 21 };

      for (let C = 0; C <= 9; ++C) {
        const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
        if (ws[cellRef]) {
          const isLeftAligned = (C === 2 || C === 3); // Member Name & Nu/Pa Hming
          ws[cellRef].s = {
            font: { name: 'Times New Roman', sz: 11, bold: false, color: { rgb: '000000' } },
            alignment: { horizontal: isLeftAligned ? 'left' : 'center', vertical: 'center' },
            border: borderThin
          };

          // Force text type for Card No, House No, Phone
          if (C === 1 || C === 4 || C === 6) {
            ws[cellRef].t = 's';
          }
        }
      }
    }

    // Freeze header row at row 6
    ws['!freeze'] = { xSplit: 0, ySplit: 6 };

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'KTP Members');

    const fileName = `Kristian_Thalai_Pawl_Armed_Veng_South_${new Date().toISOString().slice(0, 10)}.xlsx`;
    XLSX.writeFile(wb, fileName);
    showToast('Excel file auto-fixed (Mizo Synod Book Times, Centered) a download ta e!', 'success');
  } else {
    exportToExcelHtmlFallback();
  }
}

